\section{End Matter}
\twocolumngrid
\lsec{Preliminaries} Let $\SC_n$ denote the symmetric group on $n$ objects. We denote the unitary representation of $\SC_n$ on $(\mathbb{C}^d)^{\otimes n}$ by $P_d(\pi)$. Crucially, because it is a representation, we have $P_d(\pi \sigma) =P_d(\pi) P_d(\sigma)$ and $P_d(e) = \Id_d^{\otimes n}$, where $e\in \SC_n$ is the identity permutation. Let $\vee^{n}(\mathbb{C}^d) \subseteq (\mathbb{C}^d)^{\otimes n}$ denote the symmetric subspace. The projector onto this subspace can be expressed as (cf. Ref.~\cite{harrow2013Church})
\begin{align}
\Pi_{\mathrm{sym}}^{d,n} = \frac{1}{n!} \sum_{\pi \in \SC_n} P_d(\pi),
\end{align}
with the dimension of this subspace being given as
\begin{align}
     D_n := \dim\left(\vee^{n}(\mathbb{C}^d)\right) = \binom{d+n-1}{n}.
\end{align}
When the local dimension is clear from context, we let $\Pi_n \coloneq \Pi_{\mathrm{sym}}^{d,n}$ to ease notation. We define the maximally mixed state on the symmetric subspace as $\sigma^{(n)} \eqcolon \Pi_n/D_n$. Let the group of $d$-by-$d$ unitary matrices be denoted $\UC_d$. The Haar measure is the unique left- and right-invariant measure on this group. We define a Haar random state to be $\ket{\psi} = U \ket{0}$, where $U$ is sampled according to the Haar measure on $\UC_d$.  

The average of $n$ copies of a Haar random pure state yields the maximally mixed state on the symmetric subspace
\begin{align}
        \underset{U \in \UC_d}{\mathbb{E}}\left[U^{\otimes n} \ketbra{0}{0}(U^\dagger)^{\otimes n}\right] = \sigma^{(n)}.
    \end{align}
The partial transposition operation, denoted $\Gamma_S$, transposes indices $i \in S \subseteq [n]$ and leaves the others unchanged. Let $X,Y$ be bounded operators on $(\mathbb{C}^d)^{\otimes n}$. Expanding in an operator basis, one can verify $\tr{X^{\Gamma_S}} = \tr{X}$ and $\tr{X^{\Gamma_S} Y^{\Gamma_S}}= \tr{XY}$. 

We denote the SWAP operator as $\mathbb{F} = P_d((ij))$, where $(ij)$ is cycle notation indicating which indices are being swapped. A well-known fact from quantum information theory is that partially transposing half of the SWAP operator yields $d$ times the maximally entangled projector. In our notation, we write
\begin{align}
    P_d((ij))^{\Gamma_{\{i\}}} = P_d((ij))^{\Gamma_{\{j\}}} = d \psi_{i,j}.
\end{align}
Let $M \succeq 0$. Then a two-outcome POVM $\{M,\Id-M\}$ on $(\mathbb{C}^d)^{\otimes n}$ is said to be PPT-BOTH if both $M$ and $\Id-M$ remain positive after partial transposition of any subset of indices. These conditions can be succinctly summarized as
\begin{align} 
    0 \preceq M^{\Gamma_S} \preceq \Id \quad \forall~S \subseteq [n].
\end{align}
Let $A,B$ be bounded operators. The trace norm is denoted $\|A\|_1 = \tr{\sqrt{A^{\dagger}A}}$ and, when $A \succeq 0$, simplifies to $\|A\|_1=\tr{A}$. The trace norm is multiplicative over tensor products $\|A \otimes B \|_1 = \|A\|_1 \|B\|_1.$ With these facts in mind, we make two observations. First, if $X,Y \succeq 0$ and $[X,Y]=0,$ then $XY \succeq 0$. Second, if $X$ satisfies $0 \preceq X \preceq \Id$, and $Y$ is traceless and Hermitian, then $\tr{XY} \leq \frac{1}{2}\|Y\|_1$. This follows from decomposing $Y=Y_+ - Y_-$, where $Y_+, Y_- \succeq 0$ and noting that tracelessness implies $\tr{Y_+}=\tr{Y_-}=\|Y\|_1/2$. With our notation and basic facts in mind, we proceed to the proof of our main results. See the Supplemental Material for more detailed proofs, relations to prior work, and a discussion of the algorithms that saturate our lower bounds.

\lsec{Purity Testing}
As outlined in the main text, the first step in our proof is rewriting the difference of the two states using a telescoping sum. Noting that $\sigma^{(1)} = \tau_d$, we are able to write
    \begin{align}
        \Delta 
        &= \sum_{m=2}^n (\sigma^{(m)} - \sigma^{(m-1)}\otimes \tau_d)\otimes \tau_d^{\otimes (n-m)},\\
        &=  \sum_{m=2}^n \DC_m(\sigma^{(m)}) \otimes \tau_d^{\otimes (n-m)},
    \end{align}
    where we have defined $\DC_m(\sigma^{(m)}) \coloneq \sigma^{(m)} - \sigma^{(m-1)}\otimes \tau_d$, which we note is traceless and Hermitian. We may then bound the bias as
    \begin{align}
        \tr{M \Delta} &= \sum_{m=2}^n \tr{M \DC_m(\sigma^{(m)}) \otimes \tau_d^{\otimes (n-m)}}, \\
        &= \sum_{m=2}^n \tr{M^{\Gamma_m}\DC_m(\sigma^{(m)})^{\Gamma_m} \otimes \tau_d^{\otimes (n-m)} }, \\
        &\leq \sum_{m=2}^n \frac{1}{2} \left\|\DC_m(\sigma^{(m)})^{\Gamma_m} \right\|_1, 
    \end{align}
    where we have used the PPT-BOTH condition to ensure $0 \preceq M^{\Gamma_m} \preceq \Id$. This, coupled with the Hermiticity and tracelessness of $\DC_{m}(\sigma^{(m)})^{\Gamma_m}$ allows us to apply the trace norm lemma from the preliminaries. All that remains is to prove that 
    \begin{align}
        \frac{1}{2} \left\|\DC_m(\sigma^{(m)})^{\Gamma_m} \right\|_1 \leq \frac{m-1}{d+m-1},
    \end{align}
    from which the $O(n^2/d)$ bound follows simply. 

    \begin{lemma}\label{lem:last-leg-depolarize-trace-norm-bound}
    Let $\DC_m(\sigma^{(m)})= (\sigma^{(m)} - \sigma^{(m-1)}\otimes \tau_d)$ and denote the partial transposition of the $m$-th leg as $\Gamma_m$. Then, we have \begin{align}
        \frac{1}{2}\|\DC_m(\sigma^{(m)})^{\Gamma_m}\|_1 \leq \frac{m-1}{d+m-1}.
    \end{align}
\end{lemma}
\begin{proof}
    To begin, expand the symmetric subspace projector and isolate the last tensor factor \begin{align}
         \Pi_m  &= \frac{1}{m!}\sum_{\pi \in S_m}P_d(\pi), \\
        & = \frac{1}{m}\left(\Pi_{m-1} \otimes \mathbb{I}_m\right)\left(\mathbb{I} + \sum_{i=1}^{m-1}P_d((im))\right).
    \end{align}
    Taking the partial transposition of the $m$-th site yields 
    \begin{align}
          \Pi_m^{\Gamma_m}& =  \frac{1}{m}\left(\Pi_{m-1} \otimes \mathbb{I}_m\right)\left(\mathbb{I} + \sum_{i=1}^{m-1}d \psi_{i,m}\right).
    \end{align}
   To ease the remaining manipulation, define the positive operators \begin{align}
        A_m \coloneq \Pi_{m-1} \otimes \mathbb{I}_m \quad \text{and} \quad \Psi_m\coloneq \sum_{i=1}^{m-1}\psi_{i,m},
    \end{align}
    which allows us to rewrite \begin{align}
        \Pi_m^{\Gamma_m} = \frac{1}{m}A_m(\mathbb{I}+d \Psi_m).
    \end{align}
    Next, let $\pi' \in S_{m-1}$ be an arbitrary permutation of the first $m-1$ sites. Observing that $[P_d(\pi'),\Psi_m] =0$, linearity allows us to conclude that $[A_m,\Psi_m] = 0$. Thus $0 \preceq A_m\Psi_m$, which in turn implies $\|A_m\Psi_m\|_1 = \tr{A_m\Psi_m}$. With this in mind, we note that $\|A_m\|_1 = d D_{m-1}$ and $\|A_m\Psi_m\|_1 = (m-1)D_{m-1}/d.$

    With all of these facts, we may write the partially transposed single-erasure operator as \begin{align}
        &\DC_m(\sigma^{(m)})^{\Gamma_m} = \frac{1}{D_m}\Pi_m^{\Gamma_m} - \frac{1}{dD_{m-1}}\Pi_{m-1}\otimes \mathbb{I},\\
        &= \left(\frac{1}{mD_m}-\frac{1}{d D_{m-1}}\right)A_m + \frac{d}{m D_m}A_m\Psi_m
    \end{align}
    A final application of the triangle inequality and division by $2$ yields \begin{align}
        \frac{1}{2}\|\DC_m(\sigma^{(m)})^{\Gamma_m}\|_1 \leq \frac{m-1}{d+m-1},
    \end{align}
    as desired. Finally, note that the theorem statement $O(n^2/d)$ is trivial unless $n=O(\sqrt{d})$. In this regime, we may upper bound $\frac{m-1}{d+m-1} \leq \frac{m-1}{d}$. Summing from $m=2$ to $n$ yields the desired $O(n^2/d)$ upper bound. Applying the same argument to $\Id-M$ and using $\tr{\Delta}=0$ yields the two-sided bound.
\end{proof}



\lsec{Product Testing}
As mentioned in the main text, our task of distinguishing $\rho_{\mathrm{prod}}^{(n)}$ and $\rho_{\mathrm{far}}^{(n)}$ reduces to showing \begin{align}
    \abs{\tr{M(\rho_{\mathrm{prod}}^{(n)} - \tau_{d^2}^{\otimes n})}} \leq O\left(\frac{n^2}{d}\right).
\end{align}
Similar to the purity testing proof, we can rewrite the difference of these two states using a telescoping sum. Recall that $\rho_{\mathrm{prod}}^{(m)} = \sigma_A^{(m)}\tilde{\otimes} \sigma_B^{(m)}$, where $\sigma_A^{(m)}$ and $\sigma_B^{(m)}$ denote the maximally mixed states on the symmetric subspace of Alice and Bob's respective systems. It follows that the difference of states can be written as 
\begin{align}
\begin{split}
&\rho_{\mathrm{prod}}^{(n)} - \tau_{d^2}^{\otimes n} \\
&= \sum_{m=2}^n \left[\rho_{\mathrm{prod}}^{(m)} - \rho_{\mathrm{prod}}^{(m-1)} \otimes \tau_{d^2}\right]\otimes \tau_{d^2}^{\otimes(n-m)}, \\
& = \sum_{m=2}^n\left[\DC_m(\sigma_A^{(m)}) \tilde{\otimes} \sigma_B^{(m)}\right] \otimes \tau_{d^2}^{\otimes (n-m)} \\
&+ \sum_{m=2}^n\left[(\sigma_A^{(m-1)} \otimes \tau_d) \tilde{\otimes}\DC_m(\sigma_B^{(m)})\right]\otimes \tau_{d^2}^{\otimes (n-m)}.
\end{split}
\end{align}
The bias can then be upper bounded using Theorem~\ref{thm:eps-ind-PPT-purity-LB}, yielding \begin{align}
    &\abs{\tr{M(\rho_{\mathrm{prod}}^{(n)} - \tau_{d^2}^{\otimes n})}}  \\
    & \leq  \frac{1}{2}\sum_{m=2}^n\left\|\DC_m(\sigma_A^{(m)})^{\Gamma_m} \right\|_1 + \left\|\DC_m(\sigma_B^{(m)})^{\Gamma_m}\right\|_1, \\
    & \leq 2 \sum_{m=2}^n \frac{m-1}{d}, \\
    & = O\left(\frac{n^2}{d}\right).
\end{align}
