\subsection{Purity Testing Details}
\begin{theorem}[Theorem~\ref{thm:eps-ind-PPT-purity-LB} Restated]
For every $d,n\geq2$ and every PPT-BOTH measurement $\{M,\Id-M\}$,
\begin{align}
\abs{
\tr{
M\left(
\sigma^{(n)}-\tau_d^{\otimes n}
\right)
}
}
\leq
\frac{n(n-1)}{2d}.
\end{align}
Consequently, constant-bias purity testing under PPT-BOTH measurements requires $n=\Omega(\sqrt d)$ samples.
\end{theorem}
\begin{proof}
    First, note that any $\eps$-purity tester could certainly distinguish between a Haar random pure state and the maximally mixed state. Thus, if we can show that a Haar random pure state is difficult to distinguish from the maximally mixed state using only PPT-BOTH measurements, this will imply hardness of purity testing. 

    It is helpful to imagine a referee preparing, with equal probability, either the maximally mixed state $\tau_d$ or a Haar random pure state $\psi$. In either case, we will get $n$ identical copies of this state. Because we do not know what Haar random pure state we are given $n$ copies of, the density matrix representing our knowledge of the underlying system in this case is 
    \begin{align}
       \underset{U \in \UC_d}{\mathbb{E}}\left[U^{\otimes n} \ketbra{0}{0}(U^\dagger)^{\otimes n}\right] = \frac{\Pi_n}{D_n} \eqcolon \sigma^{(n)},
    \end{align}
    where we have introduced the shorthand $\Pi_n \coloneq \Pi_{\rm sym}^{d,n}$ and $D_n \coloneq \tr{\Pi_{\rm sym}^{d,n}}$, which will ease the algebraic manipulations below. Thus, distinguishing $n$ copies of a Haar random state from $n$ copies of the maximally mixed state is equivalent to distinguishing the maximally mixed state on $(\mathbb{C}^d)^{\otimes n}$ from the maximally mixed state on the symmetric subspace $\vee^n (\mathbb{C}^d)$.

    Let $\Delta \coloneq \sigma^{(n)} - \tau_d^{\otimes n}$ denote the difference of the two density operators. The assumption that a PPT-BOTH distinguisher exists is equivalent to assuming an $\Omega(1)$ lower bound on the bias. If we can establish a $O(n^2/d)$ upper bound on the bias, we may conclude 
    \begin{align}
        \Omega(1) \leq \abs{\tr{M\Delta}} \leq O\left(\frac{n^2}{d}\right) \implies n = \Omega(\sqrt{d}).
    \end{align}
    As outlined in the main text, the first step in our proof is rewriting the difference of the two states using a telescoping sum. Noting that $\sigma^{(1)} = \tau_d$, we are able to write
    \begin{align}
        \Delta &= \sigma^{(n)} - \sigma^{(n-1)}\otimes \tau_d + \sigma^{(n-1)}\otimes \tau_d - \dotsm - \sigma^{(2)} \otimes \tau_d^{\otimes (n-2)} + \sigma^{(2)} \otimes \tau_d^{\otimes (n-2)} - \tau_d^{\otimes n},\\
        &= \sum_{m=2}^n (\sigma^{(m)} - \sigma^{(m-1)}\otimes \tau_d)\otimes \tau_d^{\otimes (n-m)},\\
        &=  \sum_{m=2}^n \DC_m(\sigma^{(m)}) \otimes \tau_d^{\otimes (n-m)},
    \end{align}
    where we have defined $\DC_m(\sigma^{(m)}) \coloneq \sigma^{(m)} - \sigma^{(m-1)}\otimes \tau_d$, which we refer to as the \textit{single-depolarization operator}. Returning to bound the magnitude of the bias, we write
    \begin{align}
        \abs{\tr{M \Delta}} &= \abs{\sum_{m=2}^n \tr{M \DC_m(\sigma^{(m)}) \otimes \tau_d^{\otimes (n-m)}}}, \quad &\text{linearity of trace}\\
        &\leq \sum_{m=2}^n \abs{\tr{M\DC_m(\sigma^{(m)}) \otimes \tau_d^{\otimes (n-m)} }}, \quad &\text{triangle inequality}\\
        &= \sum_{m=2}^n \abs{\tr{M^{\Gamma_m}\DC_m(\sigma^{(m)})^{\Gamma_m} \otimes \tau_d^{\otimes (n-m)} }}, \quad \\
        &\leq \sum_{m=2}^n \frac{1}{2} \left\|\DC_m(\sigma^{(m)})^{\Gamma_m} \otimes \tau_d^{\otimes (n-m)} \right\|_1, \\
        &= \sum_{m=2}^n \frac{1}{2} \left\|\DC_m(\sigma^{(m)})^{\Gamma_m} \right\|_1, \\
        &\leq \sum_{m=2}^n \frac{m-1}{d+m-1}, \quad &\text{Lemma}~\ref{lem:last-leg-depolarize-trace-norm-bound},\\
        &\leq \sum_{m=2}^n \frac{m-1}{d}, 
    \end{align}
    which upon summing yields the desired bound
    \begin{align}
        \abs{\tr{M \Delta}} \leq \frac{n(n-1)}{2 d} = O\left(\frac{n^2}{d}\right).
    \end{align}
\end{proof}

\begin{lemma}[Lemma~\ref{lem:last-leg-depolarize-trace-norm-bound} Restated]
    Let $\DC_m(\sigma^{(m)})= (\sigma^{(m)} - \sigma^{(m-1)}\otimes \tau_d)$ and denote the partial transposition of the $m$-th leg as $\Gamma_m$. Then, we have \begin{align}
        \frac{1}{2}\|\DC_m(\sigma^{(m)})^{\Gamma_m}\|_1 \leq \frac{m-1}{d+m-1}.
    \end{align}
\end{lemma}
\begin{proof}
    To begin, let us rewrite the symmetric subspace projector as \begin{align}
        \Pi_m & = \frac{1}{m!}\sum_{\pi \in S_m}P_d(\pi), \\
        & = \frac{1}{m!}\left(\sum_{\pi'\in S_{m-1}}P_d(\pi') \otimes \mathbb{I}_m\right)\left(\mathbb{I} + \sum_{i=1}^{m-1}P_d((im))\right), \\
        & = \frac{1}{m}\left(\Pi_{m-1} \otimes \mathbb{I}_m\right)\left(\mathbb{I} + \sum_{i=1}^{m-1}P_d((im))\right), \\
        \implies \Pi_m^{\Gamma_m}& =  \frac{1}{m}\left(\Pi_{m-1} \otimes \mathbb{I}_m\right)\left(\mathbb{I} + \sum_{i=1}^{m-1}d \psi_{i,m}\right),
    \end{align}
    where $\psi_{i,m}$ is the projector onto the maximally entangled state between system $i$ and $m$. To ease the remaining manipulation, define \begin{align}
        A_m \coloneq \Pi_{m-1} \otimes \mathbb{I}_m \quad \text{and} \quad \Psi_m\coloneq \sum_{i=1}^{m-1}\psi_{i,m},
    \end{align}
    which allows us to rewrite \begin{align}
        \Pi_m^{\Gamma_m} = \frac{1}{m}A_m(\mathbb{I}+d \Psi_m).
    \end{align}
    Next, observe that $[P_d(\pi'),\Psi_m] =0$. Indeed, because $P_d(\pi')\psi_{i,m}P_d(\pi')^\dagger = \psi_{\pi'(i),m}$, we may calculate \begin{align}
        P_d(\pi')\Psi_m P_d(\pi')^\dagger = \sum_{i=1}^{m-1}\psi_{\pi'(i),m} = \sum_{j=1}^{m-1}\psi_{j,m} = \Psi_m,
    \end{align}
    and it follows from linearity that $[A_m,\Psi_m] = 0$. Thus $0 \preceq A_m\Psi_m$, which in turn implies $\|A_m\Psi_m\|_1 = \tr{A_m\Psi_m}$. With this in mind, we can strategically take partial traces to obtain \begin{align}
        \|A_m\|_1 = d D_{m-1} \quad \text{and} \quad \|A_m\Psi_m\|_1 = (m-1)\cdot \frac{D_{m-1}}{d}.
    \end{align}
    With all of these facts, we may write the partially transposed single-erasure operator as \begin{align}
        \DC_m(\sigma^{(m)})^{\Gamma_m} = \frac{1}{D_m}\Pi_m^{\Gamma_m} - \frac{1}{dD_{m-1}}\Pi_{m-1}\otimes \mathbb{I} = \left(\frac{1}{mD_m}-\frac{1}{d D_{m-1}}\right)A_m + \frac{d}{m D_m}A_m\Psi_m
    \end{align}
    A final application of the triangle inequality yields \begin{align}
        \|\DC_m(\sigma^{(m)})^{\Gamma_m}\|_1 \leq \abs{\frac{1}{mD_m}-\frac{1}{d D_{m-1}}}dD_{m-1}+\frac{d}{mD_m}(m-1)\cdot \frac{D_{m-1}}{d} = 2\frac{m-1}{d+m-1}.
    \end{align}
    Dividing by two yields the desired result.
\end{proof}

In Ref.~\cite{gong2024sample}, the authors prove an $\varepsilon$-dependent lower bound on purity estimation using the tree formalism. We note that our proof of the above theorem can easily be adapted to recover this $\varepsilon$-dependent bound as well.

\begin{proposition}[Proposition~\ref{prop:eps-dep-purity-LB} Restated]
For $0<\eps\leq1-1/d$, any PPT-BOTH purity tester with distance parameter $\eps$ requires
$n=\Omega(\sqrt{d/\eps})$
samples.
\end{proposition}

To match the testing parameter exactly, we distinguish the mixing parameter $\delta$ from the promised distance $\eps$. For $\rho_\delta
    \coloneq
    (1-\delta)\ketbra{0}{0}+\delta\tau_d,$
the closest pure state is $\ketbra{0}{0}$, and hence
\begin{align}
    \min_{\psi\ {\rm pure}}
    d_{\rm tr}(\rho_\delta,\psi)
    =
    \delta\left(1-\frac{1}{d}\right).
\end{align}
We therefore set
\begin{align}
    \delta
    \coloneq
    \frac{\eps}{1-1/d}
    =
    \frac{d}{d-1}\eps.
\end{align}
Since $\eps\leq\delta\leq2\eps$ for $d\geq2$, this rescaling does not affect the asymptotic bound.

\begin{proof}
    An $\eps$-purity tester can distinguish the Haar-random pure-state ensemble from the Haar orbit of $\rho_\delta$. Their $n$-copy average states differ by
    \begin{align}
        \Delta_\delta
        &\coloneq
        \sigma^{(n)}
        -
        \underset{U\sim{\rm Haar}}{\mathbb{E}}
        \left[
            (U\rho_\delta U^\dagger)^{\otimes n}
        \right] \\
        &=
        \sum_{S\subseteq[n]}
        (1-\delta)^{n-s}\delta^s
        \left(
            \sigma^{(n)}
            -
            \sigma_{S^c}^{(n-s)}
            \otimes\tau_{d,S}
        \right),
        \qquad s\coloneq|S|.
    \end{align}
    For each $S$, we may relabel the registers so that the $s$ maximally mixed factors occupy the last $s$ positions. Such relabeling preserves the PPT-BOTH constraint, and the same telescoping argument gives
    \begin{align}
        \abs{\tr{M\Delta_\delta}}
        &\leq
        \frac{1}{2}
        \sum_{s=0}^{n}
        {n\choose s}
        (1-\delta)^{n-s}\delta^s
        \sum_{m=n-s+1}^{n}
        \left\|
            \DC_m(\sigma^{(m)})^{\Gamma_m}
        \right\|_1 \\
        &\leq
        \frac{1}{d}
        \sum_{s=0}^{n}
        {n\choose s}
        (1-\delta)^{n-s}\delta^s
        \left(
            ns-\frac{s(s+1)}{2}
        \right) \\
        &\leq
        \frac{n^2\delta}{d}
        =
        O\left(\frac{n^2\eps}{d}\right),
    \end{align}
    where we used Proposition~\ref{lem:last-leg-depolarize-trace-norm-bound} and
    \begin{align}
        \sum_{s=0}^{n}
        {n\choose s}
        (1-\delta)^{n-s}\delta^s s
        =
        n\delta.
    \end{align}
    Constant distinguishing bias therefore requires
    $n=\Omega(\sqrt{d/\eps})$.
\end{proof}

\section{Product Testing Details}
   This appendix follows closely along the lines of Ref.~\cite{beckey2025Product}. Let us assume that a PPT-BOTH product tester exists. That is, there exists $\{M,I-M\}$ with $0\leq M \leq I$ and $0 \leq M^{\Gamma_S} \leq I$ for all $S \subseteq [n]$ for which the following hold: 
    \begin{itemize}
        \item If $\ket{\psi}$ is product, then $\tr{M \psi^{\otimes n}} \geq \frac{2}{3} =: c $
        \item If $\ket{\psi}$ is $\epsilon$-far from product, the $\tr{M \psi^{\otimes n}} \leq \frac{1}{3} =: s$.
    \end{itemize}
   This implies that for any $\psi$ which is product and any $\phi$ which is far from product, we have 
    \begin{align}
        \frac{1}{3} = b \leq \tr{M\left(\psi^{\otimes n}-\phi^{\otimes n}\right)}.
    \end{align}
    Since this holds for all states in those respective sets, and because the trace is linear, we can take an expectation over an ensemble of states that are product and an ensemble of state which are all far from product. We have
    \begin{align}
        \frac{1}{3} = b \leq \abs{\tr{M \left(\underset{\ket{\psi_A},\ket{\psi_B} \in \mathbb{C}^d}{\mathbb{E}} [\psi_A^{\otimes n} \otimes \psi_B^{\otimes n}] - \underset{\ket{\psi} \in \mathbb{C}^{d^2}}{\mathbb{E}} [\psi^{\otimes n}]\right)}}.
    \end{align}
    Now, it is clear that the ensemble on the left contains only product states. However, the ensemble on the right clearly cannot only contain states that are far from product. Among all Haar random states, either $\ket{\psi}$ is close to product, or it is far, thus we have
    \begin{align}
        \underset{\ket{\psi} \in \mathbb{C}^{d^2}}{\mathbb{E}} \left[\tr{M \psi^{\otimes n}}\right] 
        &= \underset{\ket{\psi} \in \mathbb{C}^{d^2}}{\mathbb{E}} [\tr{M \psi^{\otimes n}} \rvert \psi~\mathrm{far}] \cdot \mathrm{Prob}\left[ \psi~\mathrm{far} \right] +  \underset{\ket{\psi} \in \mathbb{C}^{d^2}}{\mathbb{E}} [\tr{M \psi^{\otimes n}} \rvert \psi~\mathrm{close}] \cdot \mathrm{Prob}\left[ \psi~\mathrm{close} \right],\\
        &\leq \frac{1}{3} \cdot \mathrm{Prob}\left[ \psi~\mathrm{far} \right] +  1 \cdot \mathrm{Prob}\left[ \psi~\mathrm{close} \right],\\
        &= \frac{1}{3} \cdot (1-\mathrm{Prob}\left[ \psi~\mathrm{close} \right]) +  1 \cdot \mathrm{Prob}\left[ \psi~\mathrm{close} \right],
    \end{align}
    which implies 
    \begin{align}
        \underset{\ket{\psi} \in \mathbb{C}^{d^2}}{\mathbb{E}} \left[\tr{M \psi^{\otimes n}}\right]&\leq \frac{1}{3} + \frac{2}{3} \cdot \mathrm{Prob}\left[ \psi~\mathrm{close} \right]
    \end{align}
    where we have bounded the first expectation by 1/3 from the assumption of the tester and the other trivially because probabilities are always at most 1. In this form, it is clear that we need to prove that the probability of obtaining a state that is close to a product state when sampling uniformly over $\mathbb{C}^{d^2}$ is highly unlikely. 

    \begin{align}
        \mathrm{Prob}\left[ \psi~\mathrm{close} \right] &:= \mathrm{Prob}\left[ \exists \ \text{product } \phi \ \text{s.t. } d_{\rm tr}\big(|\psi\rangle,|\phi\rangle\big) \le \varepsilon \right],\\
        &= \mathrm{Prob}\left[ \underset{\ket{\phi} \mathrm{product}}{\max} |\braket{\phi}{\psi}|^2 \geq 1-\varepsilon^2 \right], \\
        &=\mathrm{Prob}[\lambda_{\rm max} (\psi_A)  \geq 1-\varepsilon^2],\\
        &\leq Ce^{-cd},
    \end{align}
    where we have defined $\lambda_{\rm max} (\psi_A) := \|\gamma_A \|_{\infty}$ to be the maximal Schmidt coefficient and used concentration results from Ref.~\cite{hayden2006Aspects}.We can then utilize the following Corollary from Ref.~\cite{harrow2013Church}. Thus, using these ensembles only alters the bias by some $o(1)$ factor. Since the tester accepts product states with probability at least $2/3$,
\begin{align}
\tr{M(\rho_{\mathrm{prod}}^{(n)}-\rho_{\mathrm{Haar}}^{(n)})}
\geq
\frac13-\frac23
\Pr_{\psi\sim\mathrm{Haar}}
\!\left[
d_{\rm tr}(\psi,\mathrm{Prod})<\eps
\right]
=
\frac13-o(1).
\end{align} We are now ready to prove Theorem~\ref{thm:product-testing-LB} from the main text.

\begin{proof}[Proof of Theorem~\ref{thm:product-testing-LB}]
    As established in the preceding section, any PPT-BOTH measurement $\{M, \mathbb{I}-M\}$ functioning as a valid $\varepsilon$-product tester must have $\Omega(1)$ bias in the task of distinguishing 
    \begin{align}
        \Delta \coloneq \underset{\ket{\psi_A}, \ket{\psi_B} \in \mathbb{C}^{d}}{\mathbb{E}}\left[\psi_A^{\otimes n} \tilde{\otimes} \psi_B^{\otimes n}\right] - \underset{\ket{\psi}\in \mathbb{C}^{d^2}}{\mathbb{E}}\left[\psi^{\otimes n}\right],
    \end{align}
    where we denote $\rho_{\mathrm{prod}}^{(n)}$ and $\rho_{\mathrm{far}}^{(n)}$, respectively. If we can show such a measurement also has $O(n^2/d)$ bias, then it would follow that the sample complexity $n = \Omega(\sqrt{d})$. First, we can rewrite the bias \begin{align}
        \abs{\tr{M\Delta}} = \abs{\tr{M(\rho_{\mathrm{prod}}^{(n)} - \tau_{d^2}^{\otimes n} - (\rho_{\mathrm{far}}^{(n)} - \tau_{d^2}^{\otimes n}))}} \leq \abs{\tr{M(\rho_{\mathrm{prod}}^{(n)}  - \tau_{d^2}^{\otimes n})}} + \abs{\tr{M(\rho_{\mathrm{far}}^{(n)} - \tau_{d^2}^{\otimes n})}}.
    \end{align}
        From Theorem~\ref{thm:eps-ind-PPT-purity-LB}, by replacing $d \to d^2$, we see the second term is $O(n^2/d^2)$. Thus it suffices to show the first term is $O(n^2/d)$. In this setting, we define \begin{align}
       \rho_{\mathrm{prod}}^{(m)} \coloneq \sigma_A^{(m)} \tilde{\otimes} \sigma_B^{(m)},
       \end{align}
        where $\sigma_A^{(m)}$ and $\sigma_B^{(m)}$ are the maximally mixed states on the symmetric subspaces for Alice and Bob, respectively. Note that $\rho_{\mathrm{prod}}^{(1)} = \sigma_A^{(1)} \tilde{\otimes} \sigma_B^{(1)} = \tau_{d^2}$. Using a telescoping sum, we can then rewrite \begin{align}
        \rho_{\mathrm{prod}}^{(n)} - \tau_{d^2}^{\otimes n} & = \sum_{m=2}^n \left[\rho_{\mathrm{prod}}^{(m)} \otimes \tau_{d^2}^{\otimes(n-m)} - \rho_{\mathrm{prod}}^{(m-1)} \otimes \tau_{d^2}^{\otimes(n-m+1)}\right], \\
        & = \sum_{m=2}^n \left[(\sigma_A^{(m)}\tilde{\otimes} \sigma_B^{(m)}) - (\sigma_A^{(m-1)}\otimes \tau_d)\tilde{\otimes} (\sigma_B^{(m-1)}\otimes \tau_d) \otimes \tau_{d^2}^{\otimes (n-m)}\right], \\
        & = \sum_{m=2}^n \left[(\sigma_A^{(m)} - \sigma_A^{(m-1)}\otimes \tau_d)\tilde{\otimes}\sigma_B^{(m)} + (\sigma_A^{(m-1)}\otimes \tau_d)\tilde{\otimes} (\sigma_B^{(m)} - \sigma_B^{(m-1)}\otimes \tau_d) \right] \otimes \tau_{d^2}^{\otimes (n-m)},   \\
        & = \sum_{m=2}^n\left[\DC_m(\sigma_A^{(m)}) \tilde{\otimes} \sigma_B^{(m)} + (\sigma_A^{(m-1)}\otimes \tau_d) \tilde{\otimes} \DC_m(\sigma_B^{(m)})\right] \otimes \tau_{d^2}^{\otimes (n-m)}.
    \end{align}
    With Lemma~\ref{lem:last-leg-depolarize-trace-norm-bound}, the bias can then be upper bounded as \begin{align}
        \abs{\tr{M(\rho_{\mathrm{prod}}^{(n)}-\tau_{d^2}^{\otimes n})}} & = \abs{\tr{M\left(\sum_{m=2}^n\left[\DC_m(\sigma_A^{(m)}) \tilde{\otimes} \sigma_B^{(m)} + (\sigma_A^{(m-1)}\otimes \tau_d) \tilde{\otimes} \DC_m(\sigma_B^{(m)})\right] \otimes \tau_{d^2}^{\otimes (n-m)}\right)}},   \\
        & \leq \sum_{m=2}^n \abs{\tr{M\left(\left[\DC_m(\sigma_A^{(m)}) \tilde{\otimes} \sigma_B^{(m)} + (\sigma_A^{(m-1)}\otimes \tau_d) \tilde{\otimes} \DC_m(\sigma_B^{(m)})\right] \otimes \tau_{d^2}^{\otimes (n-m)}\right)}},   \\
        & = \sum_{m=2}^n \abs{\tr{M^{\Gamma_m}\left(\left[\DC_m(\sigma_A^{(m)}) \tilde{\otimes} \sigma_B^{(m)} + (\sigma_A^{(m-1)}\otimes \tau_d) \tilde{\otimes} \DC_m(\sigma_B^{(m)})\right] \otimes \tau_{d^2}^{\otimes (n-m)}\right)^{\Gamma_m}}}, \\
        & \leq \frac{1}{2}\sum_{m=2}^n \left\|\left[\DC_m(\sigma_A^{(m)}) \tilde{\otimes} \sigma_B^{(m)} + (\sigma_A^{(m-1)}\otimes \tau_d) \tilde{\otimes} \DC_m(\sigma_B^{(m)})\right]^{\Gamma_m}\right\|_1 , \\   
        & \leq \frac{1}{2}\sum_{m=2}^n \left\|\DC_m(\sigma_A^{(m)})^{\Gamma_m}\right\|_1\cdot \left\|(\sigma_B^{(m)})^{\Gamma_m}\right\|_1 + \left\|(\sigma_A^{(m-1)}\otimes \tau_d)\right\|_1 \cdot \left\|\DC_m(\sigma_B^{(m)})^{\Gamma_m}\right\|_1, \\
        & \leq \frac{1}{2}\sum_{m=2}^n \frac{m-1}{d}\cdot \left\|(\sigma_B^{(m)})^{\Gamma_m}\right\|_1 + \left\|(\sigma_A^{(m-1)}\otimes \tau_d)\right\|_1 \cdot \frac{m-1}{d}. 
    \end{align}
    It is clear that $\left\|(\sigma_A^{(m-1)}\otimes \tau_d)\right\|_1 = 1$ from it being a valid quantum state. Note that also $\left\|(\sigma_B^{(m)})^{\Gamma_m}\right\|_1 = 1$. To see this, recall from the proof of Lemma~\ref{lem:last-leg-depolarize-trace-norm-bound} that we may write $\Pi_m^{\Gamma_m} = \frac{1}{m}A_m(\mathbb{I} + d\Psi_m)$. Furthermore, $[A_m, \Psi_m] = 0$. Consequently, the entire operator $A_m(\mathbb{I} + d\Psi_m) = A_m + d A_m\Psi_m \succeq 0$. Thus $(\sigma_B^{(m)})^{\Gamma_m} = \frac{1}{D_m}\Pi_m^{\Gamma_m} \succeq 0$. Because trace is invariant under partial transposition, $\left\|(\sigma_B^{(m)})^{\Gamma_m}\right\|_1 = \tr{\sigma_B^{(m)}} = 1$.
    This allows us to complete the bound of the bias, as we can now write \begin{align}
        \abs{\tr{M(\rho_{\mathrm{prod}}^{(n)}-\tau_{d^2}^{\otimes n})}} & \leq 2 \sum_{m=2}^n \frac{m-1}{d} = O\left(\frac{n^2}{d}\right).
    \end{align}
\end{proof}

