    \end{align}
    Since $\rho^1_{RA}(0)=\sigma_{RA}$, we have that $\varphi(0)=0$. Moreover, $(i)$ implies that $\varphi(\lambda)\geq0$ for all $\lambda\in [0,\epsilon]$. Hence, it must be the case that $\varphi'(0)\geq 0$. The result follows from computing the derivative $\varphi'(0)$:
    \begin{align}
    \varphi'(0) &= \eta  D(\cM(\rho_{RA})\|\cM(\sigma_{RA}))  - D(\cN(\rho_{RA})\|\cN(\sigma_{RA}))  \nonumber\\
    &\quad+ \left((1-\lambda) \left.\frac{\partial}{\partial\lambda}\left[ \eta D(\cM(\rho^1_{RA}(\lambda))\|\cM(\sigma_{RA})) - D(\cN(\rho^1_{RA}(\lambda))\|\cN(\sigma_{RA}))  \right] \right)\right|_{\lambda=0}\\
    &= \eta  D(\cM(\rho_{RA})\|\cM(\sigma_{RA}))  - D(\cN(\rho_{RA})\|\cN(\sigma_{RA})), 
    \end{align}
   where the second equality follows again from~\cref{lem:prop-rel-ent}. 
\end{proof}

\cref{Thm:MIR-equivalence} implies the following result. 
\begin{corollary}\label{Cor:MIR-equals-complete}
    For a channel $\cN$, the following equalities hold:
    \begin{align}
               \etaC_D(\cN)= \eta_{\operatorname{2cqMIR}}(\cN) = \eta_{\operatorname{cqMIR}}(\cN) = \eta_{\operatorname{MIR}}(\cN).
    \end{align}
\end{corollary}
\begin{proof}
    Also here, the first two equalities follow immediately from~\cref{Thm:MIR-equivalence}.
    The third equality follows after noting that the $CR$ system in the mutual information acts as the reference system and is indeed given by the same state $\rho_{CR}=\rho_C\otimes\rho_R$ in both arguments.
\end{proof}

